-- READ ONLY. Migration 003C verification. Run each SELECT independently.
select p.proname,pg_get_function_identity_arguments(p.oid),p.prosecdef,p.proconfig,has_function_privilege(0,p.oid,'execute') public_execute,has_function_privilege('anon',p.oid,'execute') anon_execute,has_function_privilege('authenticated',p.oid,'execute') authenticated_execute,has_function_privilege('service_role',p.oid,'execute') service_execute from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('start_openingfit_mission_training_session','record_openingfit_mission_training_attempt','complete_openingfit_mission_training_session','openingfit_missions_schema_readiness') order by 1,2;
select public.openingfit_missions_schema_readiness() readiness;
select case when to_regprocedure('public.complete_openingfit_mission_training_session(uuid,uuid,uuid,text)') is not null and public.openingfit_missions_schema_readiness()->>'schemaVersion'='3' and public.openingfit_missions_schema_readiness()->>'trainingReady'='true' and not has_function_privilege(0,to_regprocedure('public.complete_openingfit_mission_training_session(uuid,uuid,uuid,text)'),'execute') and not has_function_privilege('authenticated',to_regprocedure('public.complete_openingfit_mission_training_session(uuid,uuid,uuid,text)'),'execute') and has_function_privilege('service_role',to_regprocedure('public.complete_openingfit_mission_training_session(uuid,uuid,uuid,text)'),'execute') then 'stage_complete' else 'stage_partial' end classification;
